import type { ChatMessage, ContentSegment, UserQuestionData, UserQuestionOption } from '../types';

interface BackendMessage {
  id: string;
  role: string;
  content: string;
  metadata: string | null;
}

/**
 * Convert backend message objects into ChatMessage[] for the UI.
 * Shared by ConversationContext.selectConversation and AgentContext stale-onDone refresh.
 */
export function buildChatMessages(messages: BackendMessage[]): ChatMessage[] {
  return messages.map((msg) => {
    if (msg.role !== 'assistant') {
      return { id: msg.id, role: 'user' as const, content: msg.content };
    }

    // Try to restore segments from metadata
    let segments: ContentSegment[] | undefined;
    let durationMs: number | undefined;
    if (msg.metadata) {
      try {
        const meta = typeof msg.metadata === 'string' ? JSON.parse(msg.metadata) : msg.metadata;
        if (typeof meta?.durationMs === 'number') durationMs = meta.durationMs;
        if (Array.isArray(meta?.segments)) {
          // DEBUG: log segment types from backend
          const segTypes = (meta.segments as Array<Record<string, unknown>>).map(s => s.type);
          console.log('[DEBUG buildChatMessages] segment types:', segTypes);
          const uqSegs = (meta.segments as Array<Record<string, unknown>>).filter(s => s.type === 'user_question');
          if (uqSegs.length > 0) console.log('[DEBUG buildChatMessages] user_question segments:', uqSegs);
          segments = (meta.segments as Array<Record<string, unknown>>).map((seg) => {
            const s: ContentSegment = { type: seg.type as ContentSegment['type'] };
            if (seg.text) s.text = seg.text as string;
            if ((seg.toolCallId || seg.toolName) && seg.type !== 'user_question') {
              s.toolResult = {
                toolCallId: (seg.toolCallId as string) || '',
                toolName: seg.toolName as string,
                sql: (seg.sql as string) || '',
                columns: [],
                rows: [],
                rowCount: (seg.rowCount as number) || 0,
                error: seg.error as string | undefined,
                chart_spec: seg.chart_spec as ContentSegment['chart_spec'],
              };
            }
            if (seg.subagentId) s.subagentId = seg.subagentId as string;
            if (seg.subagentName) s.subagentName = seg.subagentName as string;
            if (seg.sqlResults) s.sqlResults = seg.sqlResults as ContentSegment['sqlResults'];
            if (seg.chart_spec && seg.type === 'subagent_end') {
              s.chart_spec = seg.chart_spec as ContentSegment['chart_spec'];
            }
            if (seg.questionData && seg.type === 'user_question') {
              const qd = seg.questionData as Record<string, unknown>;
              s.questionData = {
                questionId: (qd.questionId as string) || '',
                question: (qd.question as string) || '',
                options: (Array.isArray(qd.options) ? qd.options : []) as UserQuestionOption[],
                multiSelect: (qd.multiSelect as boolean) || false,
              } as UserQuestionData;
              if (seg.userAnswer) s.userAnswer = seg.userAnswer as string[];
              if (seg.userFreeText) s.userFreeText = seg.userFreeText as string;
              if (seg.answerDurationMs) s.answerDurationMs = seg.answerDurationMs as number;
            }
            return s;
          });
        }
      } catch {
        // metadata parse failed, fall through to default
      }
    }

    // Fallback: single answer segment from content
    if (!segments) {
      segments = [{ type: 'answer' as const, text: msg.content }];
    }

    return {
      id: msg.id,
      role: 'assistant' as const,
      content: msg.content,
      segments,
      ...(durationMs != null && { durationMs }),
    };
  });
}

            else:
                tool_call_data["input"] = tool_input
            yield f"event: tool_call\ndata: {json.dumps(tool_call_data, default=str)}\n\n"
            # Track tool segment for persistence (placeholder, updated on result)
            persisted_segments.append({
                "type": "tool",
                "toolCallId": tool_id,
                "toolName": tool_name,
                "sql": sql or None,
            })
            if tool_name == "Task":
                subagent_name = tool_input.get("subagent_type", "unknown")
                subagent_prompt = tool_input.get("prompt", "")
                tool_names[tool_id] = subagent_name
                # Replace tool segment with subagent_start for subagent tools
                persisted_segments[-1] = {
                    "type": "subagent_start",
                    "subagentId": tool_id,
                    "subagentName": subagent_name,
                }
                yield f"event: subagent_start\ndata: {json.dumps({'id': tool_id, 'name': subagent_name, 'prompt': subagent_prompt})}\n\n"

            # Detect ask_user_question tool
            if "ask_user_question" in tool_name:
                print(f"[DEBUG] Detected ask_user_question tool_use: tool_id={tool_id}, tool_name={tool_name}", flush=True)
                from app.pending_questions import pending_question_store
                import asyncio as _asyncio
                for _ in range(50):
                    pending = pending_question_store.get_pending(stable_session)
                    if pending:
                        q_id = pending["question_id"]
                        q_data = pending["data"]
                        yield f"event: user_question\ndata: {json.dumps({'question_id': q_id, **q_data})}\n\n"
                        waiting_for_user = True
                        question_asked_at[tool_id] = time.time()
                        print(f"[DEBUG] Found pending question: q_id={q_id}, replacing segment idx={len(persisted_segments)-1}", flush=True)
                        # Replace generic 'tool' segment with 'user_question' for persistence
                        persisted_segments[-1] = {
                            "type": "user_question",
                            "toolCallId": tool_id,
                            "questionData": {
                                "questionId": q_id,
                                "question": q_data.get("question", ""),
                                "options": [
                                    {"label": o.get("label", ""), **({"description": o["description"]} if o.get("description") else {})}
                                    for o in q_data.get("options", [])
                                ],
                                "multiSelect": q_data.get("multi_select", False),
                            },
                        }
                        break
                    await _asyncio.sleep(0.1)

# --- Tool results from user messages ---
elif msg_type == "user":
    message_obj = msg.get("message", {})
    # The SDK attaches the subagent's actual output in
    # tool_use_result.content (a list of content blocks).
    # Extract it so we can use it for chart_spec extraction.
    tool_use_result = msg.get("tool_use_result")
    tool_use_result_text = ""
    if isinstance(tool_use_result, dict):
        tur_content = tool_use_result.get("content")
        if isinstance(tur_content, list):
            parts = []
            for item in tur_content:
                if isinstance(item, dict) and item.get("type") == "text":
                    parts.append(item.get("text", ""))
            tool_use_result_text = "\n".join(parts)
    for block in message_obj.get("content", []):
        if block.get("type") != "tool_result":
            continue
        tool_id = block.get("tool_use_id", "")

        # Skip subagent-internal tool results; capture
        # structured data for inclusion in subagent_end.
        parent_subagent_id = subagent_internal_tools.get(tool_id)
        if parent_subagent_id:
            sa_name = tool_names.get(tool_id, "")
            if "execute_sql" in sa_name:
                sa_parts = block.get("content", [])
                sa_text = ""
                if isinstance(sa_parts, list):
                    for part in sa_parts:
                        if isinstance(part, dict) and part.get("type") == "text":
                            sa_text = part.get("text", "")
                elif isinstance(sa_parts, str):
                    sa_text = sa_parts
                try:
                    sa_parsed = json.loads(sa_text)
                    for entry in subagent_sql_data.get(parent_subagent_id, []):
                        if entry.get("tool_id") == tool_id:
                            if sa_parsed.get("status") == "success":
                                entry["columns"] = sa_parsed.get("columns", [])
                                entry["rows"] = sa_parsed.get("rows", [])[:100]
                                entry["rowCount"] = sa_parsed.get("rowCount", 0)
                            elif sa_parsed.get("status") == "error":
                                entry["error"] = sa_parsed.get("error", "")
                            break
                except (json.JSONDecodeError, AttributeError):
                    pass
            continue

        name = tool_names.get(tool_id, "")
        content_parts = block.get("content", [])
        text = ""
        if isinstance(content_parts, list):
            for part in content_parts:
                if isinstance(part, dict) and part.get("type") == "text":
                    text = part.get("text", "")
        elif isinstance(content_parts, str):
            text = content_parts

        # Handle ask_user_question result: capture answer and timing in persisted segment
        if "ask_user_question" in name:
            print(f"[DEBUG] ask_user_question tool_result: tool_id={tool_id}, text={text[:200]}", flush=True)
            answered_at = time.time()
            asked_at = question_asked_at.pop(tool_id, None)
            duration_ms = int((answered_at - asked_at) * 1000) if asked_at else None
            try:
                answer_parsed = json.loads(text)
